Given a string that may contain duplicates, the task is find all unique permutations of given string in any order.Examples: Input: "ABC"Output: ["ABC", "ACB", "BAC", "BCA", "CAB", "CBA"]Explanation: Given string ABC has 6 unique permutations as "ABC", "ACB", "BAC", "BCA", "CAB" and "CBA".Input: "AAA"Output: ["AAA"]Explanation: No other unique permutations can be formed as all the characters are same.Try It YourselfTable of Content[Naive Approach] Generating All Permutations [Expected Approach] Generating Only Unique Permutations[Naive Approach] Generating All Permutations The idea is to generate all possible permutations of a given string and store them in a hash set. The generated permutations were stored in hash set, to ensures that only unique permutations are retained as hashset does not allow duplicates. Once all permutations have been generated, we transfer the permutations from hash set to the result array.This method is particularly useful when dealing with input strings that contain duplicate characters. Instead of manually handling the duplicates during the permutation generation, the use of a  unordered set simplifies the process by eliminating duplicates automatically. 
            CPP

    // C++ program to print unique permutation of string  using hash set.

#include <algorithm>
#include <iostream>
#include <string>
#include <unordered_set>
#include <vector>

using namespace std;

// Function genPermutation is used to generate all possible permutaion.
void genPermutation(int i, string &s, vector<bool> &used, 
                    string &curr, unordered_set<string>& st) {
    if (i == s.size()) {

        // Add the permutation to the result set
        st.insert(curr);
        return;
    }

    for (int j = 0; j < s.size(); j++) {
        if (!used[j]) {

            // Mark the character as used
            used[j] = true;
          	curr.push_back(s[j]);

            // Recurse with the next character
            genPermutation(i + 1, s, used, curr,st);

            // Backtrack and unmark the character
          	used[j] = false;
          	curr.pop_back();
        }
    }
}

vector<string> findPermutation(string &s) {

    // To track if a character is used
    vector<bool> used(s.size(), false);
    unordered_set<string> st;

  	string curr = "";

    // Start the recursion
    genPermutation(0, s, used, curr, st);

    // Convert the set to a vector
    vector<string> res(st.begin(), st.end());
    return res;
}

int main() {
    string s = "ABC";
    vector<string> res = findPermutation(s);

    // Print the permutations
    for (string perm: res)
        cout << perm << " ";

    return 0;
}


